def calc(expr: str) -> int | str:
    n = len(expr)
    pos = 0

    def skip_spaces() -> None:
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expr() -> int:
        nonlocal pos
        val = parse_term()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "+-":
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                if op == "+":
                    val += rhs
                else:
                    val -= rhs
            else:
                break
        return val

    def parse_term() -> int:
        nonlocal pos
        val = parse_unary()
        while True:
            skip_spaces()
            if pos < n and expr[pos] in "*/%":
                op = expr[pos]
                pos += 1
                rhs = parse_unary()
                if op == "*":
                    val *= rhs
                elif op == "/":
                    if rhs == 0:
                        raise ZeroDivisionError
                    q = abs(val) // abs(rhs)
                    val = -q if (val < 0) ^ (rhs < 0) else q
                else:
                    if rhs == 0:
                        raise ZeroDivisionError
                    r = abs(val) % abs(rhs)
                    val = -r if val < 0 else r
            else:
                break
        return val

    def parse_unary() -> int:
        nonlocal pos
        items: list[tuple[bool, int]] = []
        while True:
            neg = False
            while True:
                skip_spaces()
                if pos < n and expr[pos] == "-":
                    neg = not neg
                    pos += 1
                else:
                    break
            base = parse_atom()
            items.append((neg, base))
            skip_spaces()
            if pos < n and expr[pos] == "^":
                pos += 1
            else:
                break

        neg, acc = items.pop()
        if neg:
            acc = -acc
        while items:
            neg, base = items.pop()
            if acc < 0:
                raise ZeroDivisionError
            acc = base ** acc
            if neg:
                acc = -acc
        return acc

    def parse_atom() -> int:
        nonlocal pos
        skip_spaces()
        if expr[pos] == "(":
            pos += 1
            val = parse_expr()
            skip_spaces()
            pos += 1
            return val
        start = pos
        while pos < n and "0" <= expr[pos] <= "9":
            pos += 1
        if pos - start <= 4000:
            return int(expr[start:pos])
        res = 0
        for i in range(start, pos, 4000):
            end = min(i + 4000, pos)
            res = res * (10 ** (end - i)) + int(expr[i:end])
        return res

    try:
        return parse_expr()
    except ZeroDivisionError:
        return "error"
